import { useOrganization } from '@clerk/react'

export default function OrganizationPage() {
  const { isLoaded, organization } = useOrganization({
    memberships: { pageSize: 20 },
  })

  if (!isLoaded) return <p>Loading…</p>
  if (!organization) return <p>No active organization</p>

  return (
    <section>
      <h1>{organization.name}</h1>
      <p>Members: {organization.memberships?.count ?? 0}</p>
    </section>
  )
}

import { useOrganizationList } from '@clerk/nextjs'

export default function OrganizationSwitcher() {
  const { isLoaded, setActive, userMemberships } = useOrganizationList({
    userMemberships: { pageSize: 5, keepPreviousData: true },
  })

  if (!isLoaded) return <p>Loading…</p>

  return (
    <ul>
      {userMemberships?.data.map(({ organization }) => (
        <li key={organization.id}>
          <button onClick={() => setActive({ organization: organization.id })}>
            {organization.name}
          </button>
        </li>
      ))}
    </ul>
  )
}

